+    using DataType = KVBlockArrayForContextFMHA::DataType;
+
+    int32_t mMaxSeqs{};
+    int32_t mMaxBlocksPerSeq{};
+    int32_t mTokensPerBlock{};
+    int32_t mTokensPerBlockLog2{};
+    int32_t mBytesPerKBlock{};
+    int32_t mBytesPerVBlock{};
+    void* mKPoolPtr{};
+    void* mVPoolPtr{};
+    DataType* data{};
