+        : mMaxSeqs(batchSize)
+        , mMaxBlocksPerSeq(maxBlocksPerSeq)
+        , mTokensPerBlock(tokensPerBlock)
+        , mBytesPerKBlock(tokensPerBlock * bytesPerKToken)
+        , mBytesPerVBlock(tokensPerBlock * bytesPerVToken)
+        , mKPoolPtr(kPoolPtr)
+        , mVPoolPtr(vPoolPtr)
