+__global__ void pa_v4_fp8_dequant_kernel(pa_v4_dequant_kargs kargs)
+{
+    constexpr int D_NOPE = 448;
+    constexpr int D_ROPE = 64;
+    constexpr int D_FULL = D_NOPE + D_ROPE; // 512
+    constexpr int TILE   = 64;
