+#pragma unroll
+            for (int j = 0; j < 8; ++j) q8[t][kk][j] = qn_ptr[kb + j];
+        }
+    for (int kk = 0; kk < 2; ++kk) {
+        int kb = kk * 32 + kg * 8;
+#pragma unroll
+        for (int j = 0; j < 8; ++j) qr[kk][j] = qr_ptr[kb + j];
+    }
