+                }
+            bf16x8_t p_reg[KC];
+#pragma unroll
+            for (int c = 0; c < KC; ++c)
+#pragma unroll
+                for (int j = 0; j < 8; ++j)
+                    p_reg[c][j] = sP[ml * T::KVTILE + c * 32 + kg * 8 + j];
