+        max_rel = fmax(max_rel, d / (fabs((double)ref[i]) + 1e-6));
+    }
+    printf("QK-nope fp8-MFMA + sw-scale vs dequant ref:  max_abs=%.5f  max_rel=%.5f\n", max_abs, max_rel);
+    printf("sample S[0][0..3] gpu=[%.3f %.3f %.3f %.3f] ref=[%.3f %.3f %.3f %.3f]\n",
