+      if (throw_on_error) {
+        std::ostringstream oss;
+        oss << "Cannot safely lower a replicated packed four-bit physical "
+               "store without a proven single-replica guard. Buffer="
+            << access.buffer->name;
+        throw LayoutConflictException(oss.str());
+      }
+      return false;
+    }
