+      for (size_t i = 0; i < ownership_coordinates.relative.size(); ++i) {
+        occurrence_analyzer.Bind(
+            byte_coordinate_vars[i],
+            Range::FromMinExtent(ownership_coordinates.origins[i],
+                                 inverse_shape[i]));
+      }
+      occurrence_analyzer.Bind(
+          occurrence_var,
+          Range::FromMinExtent(Integer(0), Integer(*occurrence_extent)));
+
+      Map<Var, PrimExpr> recovered_iter_vars;
+      for (size_t i = 0; i < access.iter_vars.size(); ++i) {
+        recovered_iter_vars.Set(access.iter_vars[i]->var, recovered[i]);
+      }
+      bool coordinates_roundtrip = true;
+      for (size_t i = 0; i < ownership_coordinates.relative.size(); ++i) {
+        PrimExpr roundtrip_coordinate = occurrence_analyzer.Simplify(
+            Substitute(ownership_coordinates.relative[i], recovered_iter_vars));
+        PrimExpr expected_coordinate = occurrence_analyzer.Simplify(
+            byte_coordinate_vars[i] - ownership_coordinates.origins[i]);
+        if (!occurrence_analyzer.CanProveEqual(roundtrip_coordinate,
+                                               expected_coordinate)) {
+          coordinates_roundtrip = false;
+          break;
+        }
+      }
+      PrimExpr roundtrip_occurrence = occurrence_analyzer.Simplify(
+          Substitute(occurrence, recovered_iter_vars));
+      if (!coordinates_roundtrip || !occurrence_analyzer.CanProveEqual(
+                                        roundtrip_occurrence, occurrence_var)) {
+        if (throw_on_error) {
+          std::ostringstream oss;
+          oss << "Cannot prove packed four-bit byte ownership: the recovered "
+                 "ownership inverse does not round-trip the physical byte "
+                 "mapping. Buffer="
+              << access.buffer->name;
+          throw LayoutConflictException(oss.str());
+        }
+        return false;
+      }
+
+      owner = owner.Map([&](const PrimExpr &component) {
+        return occurrence_analyzer.Simplify(component);
+      });
+      bool occurrence_changes_owner = false;
+      for (const PrimExpr &component : owner) {
+        occurrence_changes_owner = occurrence_changes_owner ||
+                                   UsesVar(component, [&](const VarNode *var) {
+                                     return var == occurrence_var.get();
+                                   });
+      }
+      if (!occurrence_changes_owner) {
+        bool agrees_with_other_store_sites = true;
+        for (const auto &previous : proven_store_owners) {
+          bool same_storage = previous.storage.same_as(access.buffer->data);
+          bool byte_domains_overlap = !PackedStoreDomainsAreProvablyDisjoint(
+              previous.byte_domain, byte_domain, analyzer);
+          // Shaped owner expressions are comparable only within the same
+          // buffer view. Distinct aliases are comparable only when both use
+          // the canonical absolute-byte coordinate.
+          bool coordinate_bases_are_comparable =
+              previous.buffer.same_as(access.buffer) ||
+              (previous.uses_absolute_byte_offset &&
+               ownership_coordinates.uses_absolute_byte_offset);
+          bool same_owner = previous.owner.size() == owner.size();
+          if (same_owner) {
+            for (size_t i = 0; i < owner.size(); ++i) {
+              if (!analyzer->CanProveEqual(previous.owner[i], owner[i])) {
+                same_owner = false;
+                break;
+              }
+            }
+          }
+          if (same_storage && byte_domains_overlap &&
+              (!coordinate_bases_are_comparable || !same_owner)) {
+            agrees_with_other_store_sites = false;
+            break;
+          }
+        }
+        if (agrees_with_other_store_sites) {
+          proven_store_owners.push_back(
+              {access.buffer, access.buffer->data, owner, byte_domain,
+               ownership_coordinates.uses_absolute_byte_offset});
+          continue;
+        }
+      }
+    } catch (const NormalizeIterException &) {
+      // An unprovable inverse is unsafe for a non-atomic packed store.
+    } catch (const Error &) {
+      // Failed integer proof checks also make the ownership result unprovable.
+    }
+
+    if (ProvePackedSubByteStoreOwnershipByEnumeration(
+            stores, candidate, thread_index, analyzer,
+            canonical_replica_guard_guaranteed)) {
+      return true;
+    }
+
+    if (throw_on_error) {
+      std::ostringstream oss;
+      oss << "Cannot safely lower a packed four-bit store: logical elements "
+             "that share a writable byte may be assigned to different CUDA "
+             "blocks or threads. Use a byte-owned layout or rewrite the "
+             "access pattern. "
+             "Buffer="
+          << access.buffer->name << ", candidate=" << candidate->DebugOutput();
+      throw LayoutConflictException(oss.str());
+    }
+    return false;
+  }
+  return true;
