+bool CanProveInverseRoundTrip(const Array<PrimExpr> &input_shape,
+                              const Array<PrimExpr> &output_shape,
+                              const Array<PrimExpr> &forward_indices,
+                              const Array<PrimExpr> &backward_indices) {
