+  Array<Var> logical_vars;
+  Map<Var, PrimExpr> logical_substitution;
+  for (size_t i = 0; i < input_shape.size(); ++i) {
+    Var var("__layout_logical_" + std::to_string(i), input_shape[i].dtype());
